css_rules.declarations:
display: flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    padding: 16px 32px;
    border-radius: var(--pmd-hsb-radius-button);
    font-family: var(--pmd-hsb-font-body);
    font-size: 16px;
    font-weight: 600;
    line-height: 24px;
    letter-spacing: 0.75px;
    text-align: center;
    text-transform: uppercase;
    text-decoration: none;
    white-space: nowrap;
    color: var(--pmd-hsb-button-text);
    transition: background-color 0.25s ease, color 0.25s ease, border-color 0.25s ease;

background-color: var(--pmd-hsb-accent);
    border: 1px solid var(--pmd-hsb-accent);
    box-shadow:
      0 1px 2px 0 rgba(10, 13, 18, 0.05),
      inset 0 0 0 1px rgba(10, 13, 18, 0.18),
      inset 0 -2px 0 0 rgba(10, 13, 18, 0.05);

background-color: var(--pmd-hsb-text);
    border-color: var(--pmd-hsb-text);
    color: var(--pmd-hsb-bg);

display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: var(--svb-btn-h);
    padding: 0 var(--svb-btn-pad-x);
    border-radius: var(--svb-radius-btn);
    background-color: var(--svb-btn-bg);
    color: var(--svb-btn-text);
    font-weight: 600;
    font-size: var(--svb-btn-font);
    line-height: normal;
    text-transform: uppercase;
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    transition: opacity 0.2s ease;
